const KEY='teacher_workspace_v1';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const shift=n=>{let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);const schoolYear=()=>new Date().getFullYear()-(new Date().getMonth()<2?1:0);const empty=()=>({version:1,years:[schoolYear()],schools:[],students:[],counsel:[],contacts:[],notes:[],assessments:[],results:[],exams:[],tasks:[],subjectNotes:[]});
function demo(){let d=empty(),y=schoolYear();d.students=['김가람','이서윤','박도윤','최하린','정지우','윤시온'].map((name,i)=>({id:'demo-s'+i,year:y,cls:'2학년 3반',number:i+1,name,demo:true}));d.counsel=[{id:'demo-c1',studentId:'demo-s0',date:shift(-2),category:'학습',summary:'학습 계획을 함께 점검하고, 다음 주 실천 내용을 확인하기로 함.',follow:true,next:today(),done:false,demo:true},{id:'demo-c2',studentId:'demo-s2',date:shift(-1),category:'학교생활',summary:'모둠 활동에서 맡고 싶은 역할을 이야기함.',follow:true,next:shift(2),done:false,demo:true}];d.contacts=[{id:'demo-p1',studentId:'demo-s1',date:shift(-3),method:'메시지',summary:'체험학습 준비물 안내. 확인 여부를 다시 연락하기로 함.',next:today(),done:false,demo:true}];d.notes=[{id:'demo-n1',studentId:'demo-s0',date:today(),category:'수업 참여',note:'토의에서 친구의 의견을 요약하고 자신의 근거를 덧붙여 발표함.',demo:true},{id:'demo-n2',studentId:'demo-s3',date:shift(-1),category:'협력',note:'모둠 자료를 정리하고 역할 분담을 도와 활동을 마무리함.',demo:true}];d.assessments=[{id:'demo-a1',year:y,cls:'2학년 3반',title:'국어 · 독서 감상문',max:20,due:shift(2),demo:true}];d.results=d.students.map((s,i)=>({id:'demo-r'+i,assessmentId:'demo-a1',studentId:s.id,status:i===1?'미제출':i===4?'재제출':'제출',score:i===1?null:16+i%4,demo:true}));d.tasks=[{id:'demo-t1',year:y,title:'수행평가 안내문 점검',category:'평가',due:today(),priority:'높음',done:false,demo:true},{id:'demo-t2',year:y,title:'학급 활동 자료 정리',category:'학급',due:shift(-1),priority:'보통',done:false,demo:true},{id:'demo-t3',year:y,title:'다음 주 상담 일정 확인',category:'상담',due:shift(3),priority:'보통',done:false,demo:true}];d.exams=[{id:'demo-e1',studentId:'demo-s0',date:shift(-10),title:'2학기 진단평가',subject:'국어',score:82,max:100,demo:true}];return d}
function migrateRosters(data){
 data.schools??=[];data.subjectNotes??=[];data.tasks.forEach(t=>{t.role='homeroom'});
 for(const s of data.students)s.school=s.school||'학교 미지정';for(const a of data.assessments)a.school=a.school||'학교 미지정';
 const mapping=new Map();for(const s of [...data.students]){if(s.role)continue;s.role='homeroom';let id='subject-'+s.id;while(data.students.some(x=>x.id===id))id+='-copy';data.students.push({...s,id,role:'subject'});mapping.set(s.id,id)}
 for(const r of data.results)if(mapping.has(r.studentId))r.studentId=mapping.get(r.studentId);
 for(const student of data.students)if(!data.schools.some(x=>x.role===student.role&&x.name===student.school))data.schools.push({id:uid(),role:student.role,name:student.school});
 for(const a of data.assessments)if(!data.schools.some(x=>x.role==='subject'&&x.name===a.school))data.schools.push({id:uid(),role:'subject',name:a.school});
 return data;
}
