function dashboardTasks(category){return db.tasks.filter(t=>t.year===year&&taskRole(t)===role&&!t.done&&(category?t.category===category:!['학생 상담','학부모 상담'].includes(t.category)&&t.due<=today())).sort((a,b)=>a.due.localeCompare(b.due)||(a.time||'').localeCompare(b.time||''))}
