function homeDashboard(){let tasks=dashboardTasks(),cs=dashboardTasks('학생 상담'),ps=dashboardTasks('학부모 상담'),ms=missing();return heading('오늘의 교무수첩',new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'}),add('tasks','업무 추가'))+(db.students.some(s=>s.demo&&s.year===year)?`<div class="notice">가상의 학생과 예시 기록으로 둘러보는 중입니다. <button class="link" data-action="clearDemo">예시 데이터 지우기</button></div>`:'')+`<div class="stats"><div class="stat"><small>올해 등록 학생</small><strong>${students().length}<small> 명</small></strong></div><div class="stat"><small>오늘·기한 지난 업무</small><strong>${tasks.length}<small> 건</small></strong></div><div class="stat"><small>예정 및 미완료 상담</small><strong>${cs.length+ps.length}<small> 건</small></strong></div><div class="stat"><small>미제출·재제출</small><strong>${ms.length}<small> 건</small></strong></div></div><div class="grid"><section class="card"><div class="card-head"><h2>오늘 챙길 업무</h2><button class="link" data-action="nav" data-page="tasks">전체 보기</button></div>${tasks.map(taskRow).join('')||blank('오늘까지 처리할 업무가 없습니다.')}</section><section class="card"><div class="card-head"><h2>학생 상담</h2>${taskCategoryAdd('학생 상담')}</div>${cs.map(taskRow).join('')||blank('등록된 학생 상담 일정이 없습니다.')}</section><section class="card"><div class="card-head"><h2>학부모 상담</h2>${taskCategoryAdd('학부모 상담')}</div>${ps.map(taskRow).join('')||blank('등록된 학부모 상담 일정이 없습니다.')}</section><section class="card"><h2>수행평가 제출 확인</h2>${ms.slice(0,5).map(x=>`<div class="row"><div>${sLink(x.s.id)}<div class="muted">${esc(x.a.title)} · ${esc(x.a.due)}</div></div>${badge(x.r.status,x.r.status==='미제출'?'warn':'amber')}</div>`).join('')||blank('모든 제출 상태를 확인했습니다.')}<button class="link" data-action="nav" data-page="assessments">수행평가 관리 →</button></section></div><section class="card"><div class="card-head"><h2>최근 학생 누가기록</h2>${add('notes','기록')}</div>${db.notes.filter(inYear).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(r=>`<div class="row"><div>${sLink(r.studentId)} <span class="muted">${esc(r.date)} · ${esc(r.category)}</span><p>${esc(r.note)}</p></div></div>`).join('')||blank('작은 관찰부터 기록해 보세요.')}</section>`}
function studentPage(){let ss=students().filter(s=>(!classFilter||classKey(s)===classFilter)&&`${s.name} ${s.number} ${s.cls}`.includes(query));return heading(roleName()+' 학생 관리',role==='subject'?'수업을 맡은 여러 학급의 명단입니다. 담임 명단과 등록·수정·삭제가 분리됩니다.':'내 담임 학급의 명단입니다. 교과 명단과 등록·수정·삭제가 분리됩니다.',`<div class="heading-buttons"><button class="primary" data-action="bulk">＋ 학생 일괄 등록</button><button data-action="add" data-kind="students">한 명 추가</button><button id="copyRosterYear">학년도 명단 복사</button></div>`)+`<div class="toolbar"><input id="search" aria-label="학생 이름 또는 번호 검색" placeholder="이름 또는 번호 검색" value="${esc(query)}"><select id="classFilter" aria-label="학급 필터"><option value="">전체 학급</option>${[...new Set(students().map(classKey))].map(c=>`<option value="${esc(c)}" ${c===classFilter?'selected':''}>${esc(classCaption(c))}</option>`).join('')}</select><select id="studentJump" aria-label="학생 바로 선택"><option value="">학생 선택 · ${role==='subject'?'정보 수정':'프로필 열기'}</option>${ss.map(s=>`<option value="${esc(s.id)}">${esc(label(s))}</option>`).join('')}</select></div><div class="card"><div class="card-head"><h2>${year}학년도 명단</h2><span class="muted">${ss.length}명</span></div><div class="table-wrap"><table><thead><tr><th>학교</th><th>학급</th><th>번호</th><th>이름</th><th>관리</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${esc(s.school)}</td><td>${esc(s.cls)}</td><td>${s.number}</td><td>${role==='subject'?esc(s.name):`<button class="link" data-action="profile" data-id="${esc(s.id)}">${esc(s.name)}</button>`}</td><td>${editButtons('students',s.id)}</td></tr>`).join('')}</tbody></table></div>${!ss.length?blank('학생을 추가하거나 검색 조건을 바꿔 주세요.'):''}</div>`}
