function submissionPage(){let as=db.assessments.filter(a=>a.year===year&&(!schoolFilter||a.school===schoolFilter));if(!as.some(a=>a.id===assessmentId))assessmentId=as[0]?.id||'';let a=as.find(a=>a.id===assessmentId),ss=a?assessmentStudents(a):[],ms=a?ss.filter(s=>result(a.id,s.id).status!=='제출'):[];return heading('수행평가 관리','제출 상태와 점수를 입력하면 확인 대상이 자동으로 모입니다.',add('assessments','평가 만들기'))+`<div class="toolbar"><select id="assessmentSelect" aria-label="수행평가 선택"><option value="">평가 선택</option>${as.map(x=>`<option value="${esc(x.id)}" ${x.id===assessmentId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>`+(a?`<section class="card"><div class="card-head"><div><h2>${esc(a.title)}</h2><span class="muted">${esc(scopeLabel(a))} · ${a.max}점 만점 · 마감 ${esc(a.due)}</span></div><div class="heading-buttons"><button id="copyAssessment">평가·루브릭 복제</button>${editButtons('assessments',a.id)}</div></div><div class="table-wrap"><table><thead><tr><th>학생</th><th>제출 상태</th><th>점수</th><th>만점</th></tr></thead><tbody>${ss.map(s=>{let r=result(a.id,s.id);return `<tr><td>${sLink(s.id)}</td><td><select data-result="status" data-student="${esc(s.id)}" aria-label="${esc(s.name)} 제출 상태">${['제출','미제출','재제출'].map(v=>`<option ${r.status===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="number" min="0" max="${a.max}" step="0.1" data-result="score" data-student="${esc(s.id)}" aria-label="${esc(s.name)} 점수" value="${r.score??''}" ${r.status==='미제출'||a.criteria?.length?'disabled':''}></td><td>${a.max}</td></tr>`}).join('')}</tbody></table></div>${!ss.length?blank('평가 대상 학급에 학생이 없습니다.'):''}<p class="muted">변경 즉시 저장 · 루브릭 설정 시 점수는 학생별 채점에서 입력합니다. 미제출로 변경하면 해당 학생의 채점도 비워집니다.</p></section><section class="card"><h2>확인이 필요한 학생 <span class="badge">${ms.length}명</span></h2>${ms.map(s=>`<div class="row">${sLink(s.id)}${badge(result(a.id,s.id).status,'warn')}</div>`).join('')||blank('모든 학생이 제출했습니다.')}</section>`:blank('평가를 만들고 학생별 제출 상태를 관리해 보세요.'))}
