document.addEventListener('click',e=>{if(e.target.closest('#unifiedRecord'))openUnifiedRecord(['학생 상담','보호자 연락',...noteCategories].includes(noteTab)?noteTab:'특이사항')});
function noteWorkspace(){let classes=[...new Set(students().map(classKey))];if(!classes.includes(noteClass))noteClass=classes[0]||'';let roster=students().filter(s=>classKey(s)===noteClass&&s.name.includes(noteName));if(!roster.some(s=>s.id===noteStudent))noteStudent=roster[0]?.id||'';let st=student(noteStudent),all=noteRecords(),rows=filteredNotes(),tabs=['종합 보기','학생 상담','출결','교우관계','특이사항','보호자 연락','행발 모아보기'];
 return heading('우리 반 누가기록','학생을 선택해 상담·출결·관찰·보호자 연락을 이어서 기록합니다.')+'<div class="notebook"><section class="card note-roster"><h2>우리 반 학생</h2><label for="noteClass">담당 학급</label><select id="noteClass">'+classes.map(c=>'<option value="'+esc(c)+'" '+(c===noteClass?'selected':'')+'>'+esc(classCaption(c))+'</option>').join('')+'</select><label for="noteName">학생 이름 검색</label><input id="noteName" value="'+esc(noteName)+'" placeholder="학생 이름"><div class="note-mobile-select"><label for="noteStudent">학생 선택</label><select id="noteStudent"><option value="">학생 선택</option>'+roster.map(s=>'<option value="'+esc(s.id)+'" '+(s.id===noteStudent?'selected':'')+'>'+s.number+'번 '+esc(s.name)+'</option>').join('')+'</select></div><div class="note-roster-list">'+roster.map(s=>'<button data-note-student="'+esc(s.id)+'" class="'+(s.id===noteStudent?'active':'')+'">'+s.number+'번 · '+esc(s.name)+'</button>').join('')+'</div><div class="toolbar"><button data-action="nav" data-page="students">명단 관리·일괄 등록</button></div></section><div class="note-content">'+(!st?blank('학생을 등록하거나 검색 조건을 바꿔 주세요.'): '<section class="card"><div class="card-head"><div><h2>'+esc(st.name)+'</h2><span class="muted">'+year+'학년도 · '+esc(st.cls)+' · '+st.number+'번</span></div><button class="link" data-action="profile" data-id="'+esc(st.id)+'">통합 프로필</button></div><div class="stats"><div class="stat"><small>전체 기록</small><strong>'+all.length+'<small> 건</small></strong></div><div class="stat"><small>출결 기록</small><strong>'+all.filter(r=>r.kind==='notes'&&r.category==='출결').length+'<small> 건</small></strong></div><div class="stat"><small>보호자 연락</small><strong>'+all.filter(r=>r.kind==='contacts').length+'<small> 건</small></strong></div></div><div class="heading-buttons"><button class="primary" id="unifiedRecord">＋ 기록 남기기</button></div><p class="muted">출결은 입력한 기록 건수이며 공식 출결 일수와 다를 수 있습니다.</p></section><div class="note-tabs" aria-label="누가기록 분류">'+tabs.map(t=>'<button data-note-tab="'+esc(t)+'" class="'+(t===noteTab?'active':'')+'" aria-pressed="'+(t===noteTab)+'">'+t+'</button>').join('')+(noteTab==='행발 모아보기'?'<div class="notice">행동특성 및 종합의견에 참고할 관찰 기록입니다. 상담·보호자 연락·출결은 제외하고 사실에 근거한 필요한 내용을 선별해 활용하세요.</div>':'')+'</div><div class="note-filters"><label>기록 검색<input id="noteSearch" value="'+esc(noteSearch)+'" placeholder="제목·내용·분류 검색"></label><label>시작일<input id="noteFrom" type="date" value="'+esc(noteFrom)+'"></label><label>종료일<input id="noteTo" type="date" value="'+esc(noteTo)+'"></label><button id="noteClear">초기화</button></div><section class="card"><div class="card-head"><h2>'+esc(noteTab)+' <span class="muted">'+rows.length+'건</span></h2><div class="heading-buttons"><button id="noteCopy">기록 복사</button><button id="notePrint">인쇄</button></div></div>'+(noteFrom&&noteTo&&noteFrom>noteTo?blank('시작일을 종료일 이전으로 선택하세요.'):rows.map(r=>recordRow(r,r.kind)).join('')||blank('표시할 기록이 없습니다. 새 기록을 남기거나 검색 조건을 바꿔 주세요.'))+'</section>')+'</div></div>';
}
document.addEventListener('change',e=>{let el=e.target;if(el.id==='noteClass'){noteClass=el.value;noteStudent='';noteName='';render()}if(el.id==='noteStudent'){noteStudent=el.value;render()}if(el.id==='noteFrom'||el.id==='noteTo'){if(el.id==='noteFrom')noteFrom=el.value;else noteTo=el.value;render()}});
document.addEventListener('input',e=>{let el=e.target;if(['noteName','noteSearch'].includes(el.id)){let id=el.id,pos=el.selectionStart;if(id==='noteName')noteName=el.value;else noteSearch=el.value;render();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos)}});
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.noteStudent){noteStudent=b.dataset.noteStudent;render()}if(b.dataset.noteTab){noteTab=b.dataset.noteTab;render()}if(b.id==='noteClear'){noteSearch='';noteFrom='';noteTo='';render()}if(b.id==='notePrint'){document.body.classList.add('note-print');window.print();document.body.classList.remove('note-print')}if(b.id==='noteCopy'){if(noteFrom&&noteTo&&noteFrom>noteTo)return toast('기간을 확인해 주세요.');let st=student(noteStudent),text=year+'학년도 · '+label(st)+'\n'+noteTab+'\n\n'+filteredNotes().map(r=>'['+r.date+'] '+(r.group||r.category)+(r.attendance?' · '+r.attendance:'')+'\n'+(r.title?r.title+'\n':'')+r.text).join('\n\n');try{await navigator.clipboard.writeText(text);toast('화면의 기록을 복사했습니다.')}catch(err){let ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();let ok=document.execCommand('copy');ta.remove();toast(ok?'기록을 복사했습니다.':'복사하지 못했습니다. 인쇄 기능을 이용해 주세요.')}}});

function xmlEscape(value){return String(value).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function columnName(index){let result='';for(let n=index+1;n;n=Math.floor((n-1)/26))result=String.fromCharCode(65+(n-1)%26)+result;return result}
function zipFiles(files){
  const encoder=new TextEncoder(),locals=[],central=[];let offset=0;
  const make=(size)=>new Uint8Array(size),u16=(arr,at,n)=>new DataView(arr.buffer).setUint16(at,n,true),u32=(arr,at,n)=>new DataView(arr.buffer).setUint32(at,n>>>0,true);
  const crc32=data=>{let crc=0xffffffff;for(const byte of data){crc^=byte;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^0xffffffff)>>>0};
  for(const [path,xml] of files){
    const name=encoder.encode(path),data=encoder.encode(xml),crc=crc32(data),local=make(30+name.length);
    u32(local,0,0x04034b50);u16(local,4,20);u16(local,10,0);u16(local,12,33);u32(local,14,crc);u32(local,18,data.length);u32(local,22,data.length);u16(local,26,name.length);local.set(name,30);
    const entry=make(46+name.length);u32(entry,0,0x02014b50);u16(entry,4,20);u16(entry,6,20);u16(entry,14,33);u32(entry,16,crc);u32(entry,20,data.length);u32(entry,24,data.length);u16(entry,28,name.length);u32(entry,42,offset);entry.set(name,46);
    locals.push(local,data);central.push(entry);offset+=local.length+data.length;
  }
  const centralSize=central.reduce((s,a)=>s+a.length,0),end=make(22);u32(end,0,0x06054b50);u16(end,8,files.length);u16(end,10,files.length);u32(end,12,centralSize);u32(end,16,offset);
  const out=make(offset+centralSize+end.length);let cursor=0;for(const chunk of [...locals,...central,end]){out.set(chunk,cursor);cursor+=chunk.length}return out;
}
function buildXlsx(sheets){
  const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships';
  const files=[];
  files.push(['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+sheets.map((s,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>']);
  files.push(['_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="'+rel+'/officeDocument" Target="xl/workbook.xml"/></Relationships>']);
  files.push(['xl/workbook.xml','<workbook xmlns="'+ns+'" xmlns:r="'+rel+'"><sheets>'+sheets.map((s,i)=>'<sheet name="'+xmlEscape(s.name)+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join('')+'</sheets></workbook>']);
  files.push(['xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((s,i)=>'<Relationship Id="rId'+(i+1)+'" Type="'+rel+'/worksheet" Target="worksheets/sheet'+(i+1)+'.xml"/>').join('')+'<Relationship Id="rIdStyle" Type="'+rel+'/styles" Target="styles.xml"/></Relationships>']);
  files.push(['xl/styles.xml','<styleSheet xmlns="'+ns+'"><numFmts count="1"><numFmt numFmtId="164" formatCode="0.##"/></numFmts><fonts count="2"><font><sz val="11"/><name val="맑은 고딕"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="맑은 고딕"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF163E68"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>']);
  sheets.forEach((sheet,i)=>{
    const rows=sheet.rows;if(rows.length>1048576||rows[0].length>16384)throw Error('엑셀에서 지원하는 행 또는 열 개수를 초과했습니다.');
    const last=columnName(rows[0].length-1)+rows.length;
    const cols=rows[0].map((label,j)=>{const width=j<2?11:j===2?18:j===3?9:j===4?18:Math.min(44,Math.max(20,String(label).length*1.8));return '<col min="'+(j+1)+'" max="'+(j+1)+'" width="'+width+'" customWidth="1"/>'}).join('');
    const data=rows.map((row,r)=>'<row r="'+(r+1)+'" ht="'+(r===0?48:23)+'" customHeight="1">'+row.map((v,c)=>{const ref=columnName(c)+(r+1);if(v===null||v===undefined)return '<c r="'+ref+'"/>';if(typeof v==='number'&&Number.isFinite(v))return '<c r="'+ref+'" s="2"><v>'+v+'</v></c>';return '<c r="'+ref+'" s="'+(r===0?1:0)+'" t="inlineStr"><is><t xml:space="preserve">'+xmlEscape(v)+'</t></is></c>'}).join('')+'</row>').join('');
    files.push(['xl/worksheets/sheet'+(i+1)+'.xml','<worksheet xmlns="'+ns+'"><dimension ref="A1:'+last+'"/><sheetViews><sheetView workbookViewId="0"><pane xSplit="5" ySplit="1" topLeftCell="F2" activePane="bottomRight" state="frozen"/><selection pane="bottomRight" activeCell="F2" sqref="F2"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="23"/><cols>'+cols+'</cols><sheetData>'+data+'</sheetData><autoFilter ref="A1:'+last+'"/></worksheet>']);
  });
  return zipFiles(files);
}

let gradeTab='setup',gradeClass='';
function scopeLabel(a){return (a.school||'학교 미지정')+' · '+scopeClassLabel(a)}
function scopeClassLabel(a){return a.cls?.startsWith('@grade:')?a.cls.slice(7)+'학년 전체':a.cls||'전체 학급'}
function applies(a,s){return a.school===s.school&&a.year===s.year&&(!a.cls||(a.cls.startsWith('@grade:')?new RegExp('^'+a.cls.slice(7)+'\\s*학년').test(s.cls):a.cls===s.cls))}
function checkCriteria(rows,max){if(!Array.isArray(rows)||!rows.length||rows.length>100)throw Error('평가 기준을 1~100개 입력하세요.');for(let r of rows){if(!r||typeof r.name!=='string'||!r.name.trim()||r.name.length>150)throw Error('기준 이름을 입력하세요 (150자 이하).');if(!Number.isFinite(r.max)||r.max<=0||r.max>10000)throw Error('기준 배점을 확인하세요.');if(!Array.isArray(r.levels)||!r.levels.length||r.levels.length>100||r.levels.some(n=>!Number.isFinite(n)||n<0||n>r.max||Math.abs(n*100-Math.round(n*100))>0.00001)||!r.levels.includes(r.max))throw Error('선택 점수는 0~배점 사이, 소수 둘째 자리 이내로 입력하고 만점을 포함하세요.');}if(Math.abs(rows.reduce((sum,r)=>sum+r.max,0)-max)>0.00001)throw Error('기준 배점의 합계가 평가 만점과 같아야 합니다.');return rows}
function validateGradingData(d){for(let a of d.assessments)if(a.criteria!==undefined)checkCriteria(a.criteria,a.max);for(let r of d.results){let a=d.assessments.find(a=>a.id===r.assessmentId);if(r.marks!==undefined){if(!Array.isArray(r.marks)||r.marks.length>(a.criteria?.length||0)||r.marks.some((n,i)=>n!==null&&!a.criteria[i].levels.includes(n)))throw Error('백업의 루브릭 점수가 올바르지 않습니다.');}if(a.criteria?.length){let marks=r.marks||[],complete=marks.length===a.criteria.length&&marks.every(n=>n!==null),sum=complete?Math.round(marks.reduce((t,n)=>t+n,0)*100)/100:null;if(r.score!==sum||(r.status==='미제출'&&marks.some(n=>n!==null)))throw Error('백업의 채점 합계와 상태가 일치하지 않습니다.');}}}
function gradeSummary(a,s){let r=result(a.id,s.id);if(!a.criteria?.length)return {done:r.score===null||r.score===undefined?0:1,total:r.score??0,complete:r.score!==null&&r.score!==undefined,label:r.score===null||r.score===undefined?'미평가':'채점 완료'};let marks=r.marks||[],done=marks.filter(n=>n!==null&&n!==undefined).length,total=Math.round(marks.reduce((sum,n)=>sum+(n||0),0)*100)/100,complete=done===a.criteria.length;return {done,total,complete,label:complete?'채점 완료':done?'채점 중 '+done+'/'+a.criteria.length:'미평가'}}
function gradingResult(a,s){let r=db.results.find(r=>r.assessmentId===a.id&&r.studentId===s.id);if(!r){r={id:uid(),assessmentId:a.id,studentId:s.id,status:'미제출',score:null};db.results.push(r)}return r}
function assessmentPage(){let tabs=[['setup','① 평가·제출 관리'],['rubric','② 루브릭 설정'],['grading','③ 학생별 채점'],['results','④ 성적 조회']];let top='<div class="grade-tabs" aria-label="수행평가 단계">'+tabs.map(([id,t])=>'<button data-grade-tab="'+id+'" class="'+(id===gradeTab?'active':'')+'" aria-pressed="'+(id===gradeTab)+'">'+t+'</button>').join('')+'</div>';return top+(gradeTab==='setup'?submissionPage():gradeTab==='results'?gradeResultsPage():gradeDetailPage())}
function assessmentSelector(){let as=db.assessments.filter(a=>a.year===year&&(!schoolFilter||a.school===schoolFilter));if(!as.some(a=>a.id===assessmentId))assessmentId=as[0]?.id||'';return '<label>평가 선택<select id="assessmentSelect"><option value="">평가 선택</option>'+as.map(a=>'<option value="'+esc(a.id)+'" '+(a.id===assessmentId?'selected':'')+'>'+esc(a.title)+' · '+esc(scopeLabel(a))+'</option>').join('')+'</select></label>'}
function gradeDetailPage(){let selector=assessmentSelector(),a=db.assessments.find(a=>a.id===assessmentId);return heading(gradeTab==='rubric'?'루브릭 설정':'학생별 채점',gradeTab==='rubric'?'기준별 배점과 선택 가능한 부분점수를 정합니다.':'미평가와 0점을 구분하고 기준별 점수를 자동 합산합니다.')+'<div class="grade-selectors">'+selector+'</div>'+(a?(gradeTab==='rubric'?rubricEditor(a):gradingTable(a)):blank('평가·제출 관리에서 평가를 먼저 만들어 주세요.'))}
function rubricRow(r={name:'',max:'',levels:[]}){return '<div class="rubric-row"><label>평가 기준<input data-rubric="name" maxlength="150" value="'+esc(r.name)+'" required placeholder="예: 내용 이해"></label><label>배점<input data-rubric="max" type="number" min="0.01" max="10000" step="0.01" value="'+r.max+'" required></label><label>선택 점수 (쉼표 구분)<input data-rubric="levels" value="'+esc(r.levels.join(', '))+'" required placeholder="예: 10, 8, 6, 4, 0"></label><button type="button" data-rubric-remove>삭제</button></div>'}
function rubricEditor(a){return '<section class="card"><h2>'+esc(a.title)+'</h2><p class="muted">'+esc(scopeLabel(a))+' · 같은 평가를 사용하는 학급에 동일한 루브릭이 적용됩니다.</p><form id="rubricForm"><label for="rubricMax">평가 만점</label><input id="rubricMax" type="number" min="1" max="10000" step="0.01" value="'+a.max+'" required style="max-width:160px"><div id="rubricRows">'+(a.criteria?.length?a.criteria:[{name:'',max:a.max,levels:[a.max,0]}]).map(rubricRow).join('')+'</div><div class="toolbar"><button type="button" id="rubricAdd">＋ 기준 추가</button><span id="rubricSum" class="muted">배점 합계: '+(a.criteria?.reduce((sum,r)=>sum+r.max,0)||a.max)+'점</span></div><div class="notice">채점된 평가의 루브릭을 바꾸면 해당 평가의 모든 학생 점수가 초기화됩니다. 저장 전에 확인합니다.</div><div id="rubricError" class="error" role="alert"></div><button class="primary" type="submit">루브릭 저장</button></form></section>'}
function gradeClassSelector(ss){let classes=[...new Set(ss.map(classKey))];if(gradeClass&&!classes.includes(gradeClass))gradeClass='';return '<label>채점·조회 학급<select id="gradeClass"><option value="">전체 학급</option>'+classes.map(c=>'<option value="'+esc(c)+'" '+(c===gradeClass?'selected':'')+'>'+esc(classCaption(c))+'</option>').join('')+'</select></label>'}
function gradingTable(a){let all=assessmentStudents(a),selector=gradeClassSelector(all),ss=all.filter(s=>!gradeClass||classKey(s)===gradeClass);if(!a.criteria?.length)return '<section class="card">'+blank('루브릭 설정에서 기준을 저장하면 기준별로 채점할 수 있습니다. 총점만 입력하려면 평가·제출 관리 화면을 이용하세요.')+'</section>';return '<div class="grade-selectors">'+selector+'</div><section class="card"><div class="card-head"><h2>'+esc(a.title)+'</h2>'+badge(a.max+'점 만점')+'</div><p class="muted">제출·재제출 상태에서 채점할 수 있습니다. 빈칸은 미평가, 0점은 채점한 점수입니다. 부분 합계는 참고용이며 모든 기준을 채점하면 총점이 확정됩니다.</p><div class="table-wrap"><table class="grade-table"><thead><tr><th>학급 · 번호 · 이름</th><th>제출 상태</th>'+a.criteria.map(c=>'<th>'+esc(c.name)+'<br>'+c.max+'점</th>').join('')+'<th>현재 합계</th><th>채점 상태</th></tr></thead><tbody>'+ss.map(s=>{let r=result(a.id,s.id),g=gradeSummary(a,s);return '<tr><td>'+esc(label(s))+'</td><td><select data-result="status" data-student="'+esc(s.id)+'" aria-label="'+esc(s.name)+' 제출 상태">'+['제출','미제출','재제출'].map(v=>'<option '+(r.status===v?'selected':'')+'>'+v+'</option>').join('')+'</select></td>'+a.criteria.map((c,i)=>'<td><select data-mark="'+i+'" data-sid="'+esc(s.id)+'" aria-label="'+esc(s.name+' '+c.name)+'" '+(r.status==='미제출'?'disabled':'')+'><option value="">미평가</option>'+c.levels.map(n=>'<option value="'+n+'" '+(r.marks?.[i]===n?'selected':'')+'>'+n+'점</option>').join('')+'</select></td>').join('')+'<td class="score-cell">'+(g.done?g.total:'—')+' / '+a.max+'</td><td>'+esc(g.label)+'</td></tr>'}).join('')+'</tbody></table></div>'+(!ss.length?blank('학생 관리에서 해당 학급의 학생을 등록해 주세요.'):'')+'</section>'}
function gradeResultsPage(){let as=db.assessments.filter(a=>a.year===year&&(!schoolFilter||a.school===schoolFilter)),all=students(),selector=gradeClassSelector(all),ss=all.filter(s=>!gradeClass||classKey(s)===gradeClass);if(gradeClass)as=as.filter(a=>ss.some(s=>applies(a,s)));let done=ss.filter(s=>{let targets=as.filter(a=>applies(a,s));return targets.length&&targets.every(a=>gradeSummary(a,s).complete)}).length;return heading('성적 조회','선택한 학급의 평가별 점수와 채점 상태를 확인합니다.','<div class="heading-buttons"><button class="primary" id="templateExport">일괄등록 양식 내보내기</button><button id="gradeExport">성적 집계 엑셀</button></div>')+'<div class="grade-selectors">'+selector+'</div><div class="stats"><div class="stat"><small>평가 유형</small><strong>'+as.length+'<small>개</small></strong></div><div class="stat"><small>조회 학생</small><strong>'+ss.length+'<small>명</small></strong></div><div class="stat"><small>모든 대상 평가 채점 완료</small><strong>'+done+'<small>명</small></strong></div></div><section class="card"><div class="table-wrap"><table class="grade-table"><thead><tr><th>학급 · 번호 · 이름</th>'+as.map(a=>'<th>'+esc(a.title)+'<br>'+a.max+'점</th>').join('')+'<th>현재 합계 / 대상 만점</th><th>완료 평가</th></tr></thead><tbody>'+ss.map(s=>{let targets=as.filter(a=>applies(a,s)),items=targets.map(a=>gradeSummary(a,s)),total=Math.round(items.reduce((n,r)=>n+r.total,0)*100)/100;return '<tr><td>'+esc(label(s))+'</td>'+as.map(a=>{if(!applies(a,s))return '<td>대상 아님</td>';let r=gradeSummary(a,s);return '<td>'+(r.done?r.total+'점':'—')+'<div class="muted">'+esc(r.label)+'</div></td>'}).join('')+'<td class="score-cell">'+(items.some(r=>r.done)?total:'—')+' / '+targets.reduce((n,a)=>n+a.max,0)+'</td><td>'+items.filter(r=>r.complete).length+' / '+targets.length+'</td></tr>'}).join('')+'</tbody></table></div>'+(!ss.length?blank('학생 관리에서 학생을 먼저 등록해 주세요.'):'')+'<p class="muted">현재 합계에는 채점 중인 부분점수가 포함됩니다. 대상이 아닌 평가는 합계와 만점에서 제외합니다.</p></section>'}
let rubricDirty=false;
document.addEventListener('click',e=>{if(!rubricDirty)return;let b=e.target.closest('button');if(!b)return;if(b.matches('[data-grade-tab],[data-action="nav"],[data-action="role"],[data-action="profile"]')){if(!confirm('저장하지 않은 루브릭 변경을 버리고 이동할까요?')){e.preventDefault();e.stopImmediatePropagation()}else rubricDirty=false;}},true);
document.addEventListener('change',e=>{if(rubricDirty&&['assessmentSelect','year'].includes(e.target.id)){if(!confirm('저장하지 않은 루브릭 변경을 버리고 이동할까요?')){e.target.value=e.target.id==='year'?year:assessmentId;e.stopImmediatePropagation();return}rubricDirty=false}},true);
window.addEventListener('beforeunload',e=>{if(rubricDirty){e.preventDefault();e.returnValue=''}});
document.addEventListener('input',e=>{if(e.target.closest('#rubricForm')){rubricDirty=true;$('#rubricSum').textContent='배점 합계: '+Math.round([...document.querySelectorAll('[data-rubric=max]')].reduce((n,el)=>n+Number(el.value),0)*100)/100+'점'}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.gradeTab){gradeTab=b.dataset.gradeTab;render()}if(b.id==='rubricAdd'){$('#rubricRows').insertAdjacentHTML('beforeend',rubricRow());rubricDirty=true}if(b.hasAttribute('data-rubric-remove')){b.closest('.rubric-row').remove();rubricDirty=true;$('#rubricSum').textContent='배점 합계: '+[...document.querySelectorAll('[data-rubric=max]')].reduce((n,el)=>n+Number(el.value),0)+'점'}if(b.id==='gradeExport')exportGrades()});
document.addEventListener('submit',e=>{if(e.target.id!=='rubricForm')return;e.preventDefault();let a=db.assessments.find(a=>a.id===assessmentId);try{let max=Number($('#rubricMax').value),criteria=[...document.querySelectorAll('.rubric-row')].map(row=>({name:row.querySelector('[data-rubric=name]').value.trim(),max:Number(row.querySelector('[data-rubric=max]').value),levels:row.querySelector('[data-rubric=levels]').value.split(',').map(v=>v.trim()===''?NaN:Number(v.trim()))}));checkCriteria(criteria,max);criteria.forEach(c=>c.levels=[...new Set(c.levels)].sort((a,b)=>b-a));let changed=JSON.stringify(criteria)!==JSON.stringify(a.criteria)||a.max!==max,graded=db.results.some(r=>r.assessmentId===a.id&&(r.score!==null||r.marks?.some(n=>n!==null)));if(changed&&graded&&!confirm('루브릭을 변경하면 이 평가를 사용하는 모든 학급의 학생 점수가 초기화됩니다. 저장할까요?'))return;let next=JSON.parse(JSON.stringify(db)),target=next.assessments.find(x=>x.id===a.id);target.max=max;target.criteria=criteria;if(changed)next.results.forEach(r=>{if(r.assessmentId===a.id){r.score=null;r.marks=[]}});if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next;rubricDirty=false;render();toast('루브릭을 저장했습니다.')}catch(err){$('#rubricError').textContent=err.message}});
document.addEventListener('change',e=>{let el=e.target;if(el.id==='gradeClass'){gradeClass=el.value;render()}if(el.hasAttribute('data-mark')){let a=db.assessments.find(a=>a.id===assessmentId),s=student(el.dataset.sid),i=Number(el.dataset.mark),r=gradingResult(a,s);if(r.status==='미제출')return;let value=el.value===''?null:Number(el.value);if(value!==null&&!a.criteria[i].levels.includes(value))return;r.marks=Array.from({length:a.criteria.length},(_,j)=>r.marks?.[j]??null);r.marks[i]=value;let g=gradeSummary(a,s);r.score=g.complete?g.total:null;save();render()}});
function exportGrades(){let ss=students().filter(s=>!gradeClass||classKey(s)===gradeClass),as=db.assessments.filter(a=>a.year===year&&ss.some(s=>applies(a,s)));if(!ss.length||!as.length)return toast('내보낼 학생과 평가가 필요합니다.');let summary=[['학교','학년도','학급','번호','이름',...as.flatMap(a=>[a.title+' 점수',a.title+' 상태']),'현재 합계','대상 만점']],detail=[['학교','학년도','학급','번호','이름','평가','제출 상태','기준','배점','점수','채점 상태']];for(let s of ss){let sum=0,has=false,max=0,values=[];for(let a of as){if(!applies(a,s)){values.push(null,'대상 아님');continue}let r=result(a.id,s.id),g=gradeSummary(a,s);sum+=g.total;max+=a.max;has=has||!!g.done;values.push(g.done?g.total:null,g.label);for(let [i,c] of (a.criteria?.length?a.criteria:[{name:'총점 입력',max:a.max}]).entries()){let score=a.criteria?.length?r.marks?.[i]??null:r.score;detail.push([s.school,year,s.cls,s.number,s.name,a.title,r.status,c.name,c.max,score,score===null?'미평가':'채점 완료'])}}summary.push([s.school,year,s.cls,s.number,s.name,...values,has?Math.round(sum*100)/100:null,max])}try{let bytes=buildXlsx([{name:'성적 집계',rows:summary},{name:'루브릭 상세',rows:detail}]),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download=('수행평가_'+year+'_'+(gradeClass||'전체학급')+'.xlsx').replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('성적 집계와 루브릭 상세를 내보냈습니다.')}catch(e){toast('내보내기 실패: '+e.message)}}

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||!['registerSchool','renameSchool'].includes(b.id))return;let rename=b.id==='renameSchool';if(rename&&!schoolFilter)return;let value=prompt(roleName()+' '+(rename?'학교 이름 수정':'학교 등록')+' — 다른 역할의 학교에는 영향을 주지 않습니다.',rename?schoolFilter:'');if(value===null)return;let name=value.trim();if(!name||name.length>150)return toast('학교 이름을 1~150자로 입력하세요.');if(db.schools.some(x=>x.role===role&&x.name===name)){if(name===schoolFilter&&rename)return;return toast('이 역할에 이미 등록된 학교입니다.');}let next=JSON.parse(JSON.stringify(db));if(rename){let school=next.schools.find(x=>x.role===role&&x.name===schoolFilter);if(!school)return;school.name=name;next.students.forEach(x=>{if(x.role===role&&x.school===schoolFilter)x.school=name});if(role==='subject')next.assessments.forEach(x=>{if(x.school===schoolFilter)x.school=name});}else next.schools.push({id:uid(),name,role});try{if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next;schoolFilter=name;render();toast(rename?'이 역할의 학교 이름을 수정했습니다.':'학교를 등록했습니다. 학생이 없어도 평가를 만들 수 있습니다.');}catch(err){toast('학교를 저장하지 못했습니다. 브라우저 저장 공간을 확인하세요.');}});

function backupStamp(){let value;try{value=workspaceStorage.getItem(KEY+'_backupAt')}catch(e){}return value&&!Number.isNaN(Date.parse(value))?'최근 백업 다운로드 요청: '+new Date(value).toLocaleString('ko-KR'):'아직 백업한 기록이 없습니다.'}
function updateFocus(){let bar=$('#focusContext');if(bar)bar.textContent=year+'학년도 · '+roleName()+' · '+(schoolFilter||'전체 학교');}
$('#focusToggle').onclick=()=>{let on=document.body.classList.toggle('focus-mode');$('#focusToggle').textContent=on?'설정 펼치기 ↓':'설정 접기 ↑';$('#focusToggle').setAttribute('aria-expanded',String(!on));try{workspaceStorage.setItem(KEY+'_focus',String(on))}catch(e){}updateFocus();window.scrollTo(0,0)};
try{if(workspaceStorage.getItem(KEY+'_focus')==='true'){$('#focusToggle').click()}}catch(e){}
function utilityDialog(title,content,submit){let d=$('#utilityDialog');if(!d){d=document.createElement('dialog');d.id='utilityDialog';document.body.appendChild(d)}d.innerHTML='<form id="utilityForm"><h2>'+title+'</h2>'+content+'<div class="error" id="utilityError" role="alert"></div><div class="form-actions"><button type="button" id="utilityCancel">취소</button><button class="primary" type="submit">복사하기</button></div></form>';$('#utilityCancel').onclick=()=>d.close();$('#utilityForm').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));}catch(err){$('#utilityError').textContent=err.message}};d.showModal()}
function commitUtility(next){if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next;$('#utilityDialog').close();render()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='copyRosterYear'){
 let groups=[...new Set(db.students.filter(s=>s.role===role).map(s=>JSON.stringify([s.year,s.school,s.cls])))].map(v=>JSON.parse(v));if(!groups.length)return toast('복사할 학생 명단이 없습니다.');
 utilityDialog('학년도 명단 복사','<p class="muted">'+roleName()+' 명단 안에서 학생 이름·번호만 새로 등록합니다. 상담·누가기록·점수는 복사하지 않습니다. 대상의 중복 번호는 건너뜁니다.</p><div class="fields">'+field('source','가져올 명단','select','0',{wide:true,options:groups.map((g,i)=>[i,g[0]+' · '+g[1]+' · '+g[2]])})+field('targetYear','등록할 학년도','number',year,{min:2000,max:2200})+field('targetSchool','등록할 학교','select',schoolFilter||'',{options:db.schools.filter(s=>s.role===role).map(s=>[s.name,s.name])})+field('targetClass','등록할 학급','text','',{wide:true})+'</div>',form=>{let [sy,school,cls]=groups[Number(form.get('source'))],ty=Number(form.get('targetYear')),ts=String(form.get('targetSchool')),tc=String(form.get('targetClass')).trim();if(!tc||!Number.isInteger(ty)||ty<2000||ty>2200)throw Error('학년도와 학급을 확인하세요.');if(sy===ty&&school===ts&&cls===tc)throw Error('원본과 다른 학년도 또는 학급을 선택하세요.');let next=JSON.parse(JSON.stringify(db)),source=db.students.filter(s=>s.role===role&&s.year===sy&&s.school===school&&s.cls===cls),seen=new Set(db.students.filter(s=>s.role===role&&s.year===ty&&s.school===ts&&s.cls===tc).map(s=>s.number)),added=0;for(let s of source){if(seen.has(s.number))continue;next.students.push({id:uid(),role,year:ty,school:ts,cls:tc,number:s.number,name:s.name});seen.add(s.number);added++}if(!added)throw Error('모든 번호가 이미 등록되어 있습니다.');if(!next.years.includes(ty))next.years.push(ty);commitUtility(next);year=ty;schoolFilter=ts;classFilter=JSON.stringify([ts,tc]);render();toast(added+'명 복사 · 중복 '+(source.length-added)+'명 제외');});
}if(b.id==='copyAssessment'){
 let a=db.assessments.find(a=>a.id===assessmentId);if(!a)return;
 utilityDialog('평가·루브릭 복제','<p class="muted">평가 기준과 배점만 복제합니다. 학생 점수와 제출 상태는 복사하지 않습니다.</p><div class="fields">'+field('title','새 평가명','text',a.title+' (복사)',{wide:true})+field('year','학년도','number',year,{min:2000,max:2200})+field('school','학교','select',a.school,{options:db.schools.filter(s=>s.role==='subject').map(s=>[s.name,s.name])})+field('due','마감일','date',today())+field('cls','대상 범위','select',a.cls,{required:false,options:[['','전체 학급'],...['1','2','3'].map(g=>['@grade:'+g,g+'학년 전체']),...[...new Set(db.students.filter(s=>s.role==='subject').map(s=>s.cls))].map(c=>[c,c])]})+'</div>',form=>{let title=String(form.get('title')).trim(),y=Number(form.get('year')),school=String(form.get('school'));if(!title||!Number.isInteger(y)||y<2000||y>2200)throw Error('평가명과 학년도를 확인하세요.');let next=JSON.parse(JSON.stringify(db)),copy={...JSON.parse(JSON.stringify(a)),id:uid(),title,year:y,school,due:String(form.get('due')),cls:String(form.get('cls'))};delete copy.demo;next.assessments.push(copy);if(!next.years.includes(y))next.years.push(y);commitUtility(next);year=y;schoolFilter=school;assessmentId=copy.id;render();toast('점수 없이 평가와 루브릭을 복제했습니다.');});
}});


function classKey(s){return JSON.stringify([s.school||'학교 미지정',s.cls])}
function classCaption(key){try{return JSON.parse(key).join(' · ')}catch(e){return key}}
let formBaseline='';function formSnapshot(){return JSON.stringify([...$('#form').elements].filter(e=>e.name).map(e=>[e.name,e.type==='checkbox'?e.checked:e.value]))}
function allowFormClose(){return formSnapshot()===formBaseline||confirm('작성 중인 변경을 저장하지 않고 닫을까요?')}
$('#modal').addEventListener('cancel',e=>{if(!allowFormClose())e.preventDefault()});
window.addEventListener('beforeunload',e=>{if($('#modal').open&&formSnapshot()!==formBaseline){e.preventDefault();e.returnValue=''}});
function readTrash(){try{let a=JSON.parse(workspaceStorage.getItem(KEY+'_trash')||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}
function archiveDeletion(k,id){try{let item=db[k].find(x=>x.id===id);if(!item)return false;let rows={[k]:[item]};if(k==='students')for(let key of ['notes','counsel','contacts','exams','results','subjectNotes'])rows[key]=db[key].filter(r=>r.studentId===id);if(k==='assessments')rows.results=db.results.filter(r=>r.assessmentId===id);let list=readTrash();list.unshift({id:uid(),time:new Date().toISOString(),label:(item.name||item.title||item.summary||item.note||'기록').slice(0,80),rows});workspaceStorage.setItem(KEY+'_trash',JSON.stringify(list.slice(0,30)));return true}catch(e){toast('복구용 사본을 저장하지 못해 삭제를 중단했습니다.');return false}}
function trashHTML(){return readTrash().map(t=>'<div class="row"><div>'+esc(t.label)+'<div class="muted">'+esc(new Date(t.time).toLocaleString('ko-KR'))+'</div></div><button data-restore="'+esc(t.id)+'">복구</button></div>').join('')||blank('복구할 삭제 기록이 없습니다.')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-restore]');if(!b)return;let trash=readTrash(),entry=trash.find(t=>t.id===b.dataset.restore);if(!entry)return;try{let next=JSON.parse(JSON.stringify(db));for(let [k,rows] of Object.entries(entry.rows)){if(!Array.isArray(next[k])||!Array.isArray(rows))throw Error('복구 자료 형식이 올바르지 않습니다.');for(let r of rows){if(next[k].some(x=>x.id===r.id))throw Error('같은 기록이 이미 존재합니다.');next[k].push(r)}}next=validate(next);migrateRosters(next);persistData(JSON.stringify(next));db=next;try{workspaceStorage.setItem(KEY+'_trash',JSON.stringify(trash.filter(t=>t.id!==entry.id)))}catch(e){}render();toast('연결된 기록과 함께 복구했습니다.')}catch(e){alert('복구하지 못했습니다. 같은 번호가 등록되어 있거나 연결 학생·평가가 없을 수 있습니다. 기존 자료는 유지됩니다.')}});
