function localFontStore(action,id,bytes){return new Promise((resolve,reject)=>{let req=indexedDB.open('teacher-workspace-fonts',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(req.error);req.onsuccess=()=>{let db=req.result,tx=db.transaction('files',action==='get'?'readonly':'readwrite'),store=tx.objectStore('files'),result;let op=action==='get'?store.get(id):action==='put'?store.put(bytes,id):store.delete(id);op.onsuccess=()=>{result=op.result};tx.oncomplete=()=>{db.close();resolve(result)};tx.onabort=tx.onerror=()=>{db.close();reject(tx.error||Error('글꼴 저장 공간을 사용할 수 없습니다.'))};};});}
const cloudFontCache=new Map();
async function fontStore(action,id,bytes){
 const url='/api/fonts/'+encodeURIComponent(id);
 if(action==='delete'){cloudFontCache.delete(id);return;} // Keep immutable files for other open tabs and saved references.
 if(action==='put'){
  const response=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/octet-stream'},body:bytes,signal:AbortSignal.timeout(60000)});
  if(!response.ok)throw Error('글꼴 서버 업로드 실패. 연결과 파일 크기를 확인하세요.');
  cloudFontCache.set(id,bytes);return;
 }
 if(cloudFontCache.has(id))return cloudFontCache.get(id);
 const pending=(async()=>{
  const response=await fetch(url,{signal:AbortSignal.timeout(60000)});
  if(response.ok)return response.arrayBuffer();
  if(response.status!==404)throw Error('서버 글꼴을 불러오지 못했습니다.');
  const old=await localFontStore('get',id);
  if(!old)throw Error('기존 글꼴을 사용하던 기기에서 앱을 열거나 글꼴 파일을 다시 선택하세요.');
  await fontStore('put',id,old);return old;
 })();
 cloudFontCache.set(id,pending);
 try{return await pending;}catch(e){cloudFontCache.delete(id);throw e;}
}
