async function applyFontPrefs(prefs){let revision=++fontApplyRevision;document.documentElement.style.setProperty('--reading-line',String(prefs.line||1.6));if(prefs.data||prefs.fontId){let source=prefs.data?'url('+prefs.data+')':await fontStore('get',prefs.fontId);if(!source)throw Error('저장한 글꼴 파일이 없습니다. 다시 선택하세요.');let face=new FontFace('TeacherCustom', source,{sizeAdjust:(prefs.scale||100)+'%',ascentOverride:'90%',descentOverride:'22%',lineGapOverride:'0%'});await face.load();if(revision!==fontApplyRevision)return;if(activeFontFace)document.fonts.delete(activeFontFace);document.fonts.add(face);activeFontFace=face;document.documentElement.style.setProperty('--user-font','TeacherCustom');}else{let name=prefs.name||'Malgun Gothic';try{let face=new FontFace('TeacherLocal','local('+JSON.stringify(name)+')',{sizeAdjust:(prefs.scale||100)+'%',ascentOverride:'90%',descentOverride:'22%',lineGapOverride:'0%'});await face.load();if(revision!==fontApplyRevision)return;if(activeFontFace)document.fonts.delete(activeFontFace);document.fonts.add(face);activeFontFace=face;document.documentElement.style.setProperty('--user-font','TeacherLocal');}catch(e){if(revision===fontApplyRevision)document.documentElement.style.setProperty('--user-font',JSON.stringify(name));}}}
function fontSettingsHTML(){let all=getFontPrefs(),f=fontEditingScope==='all'?all:(all.tabs?.[fontEditingScope]||all);return '<section class="card"><h2>글꼴 설정</h2><p class="muted">업로드한 글꼴 파일과 설정은 서버에 저장되어 다른 기기에서도 적용됩니다. 이름만 입력한 PC 설치 글꼴은 해당 기기에 설치되어 있어야 합니다.</p><form id="fontForm"><label class="font-target">적용 범위<select id="fontScope">'+fontScopeOptions()+'</select></label><p class="muted">전체 기본 또는 특정 탭을 선택하세요. 탭 설정은 담임 / 교과를 구분하며 다른 탭에 영향을 주지 않습니다.</p><div class="font-options"><label>PC에 설치한 글꼴 이름<input id="fontName" maxlength="100" list="fontNames" value="'+esc(f.name||'Malgun Gothic')+'" placeholder="예: 맑은 고딕, 나눔고딕"><datalist id="fontNames"><option value="Malgun Gothic"><option value="맑은 고딕"><option value="나눔고딕"><option value="Pretendard"><option value="Noto Sans KR"><option value="Arial"></datalist></label><label>저장한 글꼴 파일 (선택)<input id="fontFile" type="file" accept=".woff2,.woff,.ttf,.otf"></label></div><p class="muted">WOFF2·WOFF·TTF·OTF, 최대 50MB. 파일을 선택하면 설치 글꼴 이름보다 우선 적용합니다. 현재: '+esc((f.data||f.fontId)?(f.fileName||'불러온 글꼴'):f.name||'기본 글꼴')+'</p><div class="font-options"><label>글자 크기 보정<select id="fontScale">'+Array.from({length:12},(_,i)=>50+i*10).map(n=>'<option value="'+n+'" '+(n===(f.scale||100)?'selected':'')+'>'+n+'%</option>').join('')+'</select></label><label>본문 줄 간격<select id="fontLine">'+Array.from({length:9},(_,i)=>(8+i)/10).map(n=>'<option value="'+n+'" '+(n===Math.max(.8,Math.min(1.6,f.line||1.6))?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><p class="muted">손글씨처럼 작게 보이는 글꼴은 120~130%로 보정해 보세요. 파일을 다시 선택하지 않아도 보정값을 저장할 수 있습니다.</p><div class="font-preview">우리 반의 하루와 성장을 기록합니다. ABC 123 · 상담 / 수행평가</div><div class="toolbar"><button class="primary" type="submit">글꼴 적용·저장</button><button id="fontReset" type="button">기본 글꼴로</button></div><div id="fontError" class="error" role="alert"></div></form></section>'}

