function setupTaskTime(){let input=$('#f-time'),value=input.value;input.type='hidden';let wrap=document.createElement('div');wrap.className='task-time-picker';wrap.innerHTML='<label><input type="checkbox" id="taskAllDay" '+(!value?'checked':'')+'> 종일</label><div class="task-time-selects"><select id="taskHour" aria-label="시">'+Array.from({length:24},(_,i)=>'<option value="'+String(i).padStart(2,'0')+'">'+String(i).padStart(2,'0')+'시</option>').join('')+'</select><select id="taskMinute" aria-label="분">'+Array.from({length:60},(_,i)=>'<option value="'+String(i).padStart(2,'0')+'">'+String(i).padStart(2,'0')+'분</option>').join('')+'</select></div><div class="task-time-shortcuts">'+['09:00','12:00','13:00','15:00','16:00'].map(t=>'<button type="button" data-quick-time="'+t+'">'+t+'</button>').join('')+'</div>';input.after(wrap);input.previousElementSibling.textContent='시간';input.previousElementSibling.htmlFor='taskHour';$('#taskHour').value=value?value.slice(0,2):'09';$('#taskMinute').value=value?value.slice(3):'00';let sync=()=>{let all=$('#taskAllDay').checked;$('#taskHour').disabled=all;$('#taskMinute').disabled=all;input.value=all?'':$('#taskHour').value+':'+$('#taskMinute').value};wrap.onchange=sync;wrap.querySelectorAll('[data-quick-time]').forEach(b=>b.onclick=()=>{$('#taskAllDay').checked=false;$('#taskHour').value=b.dataset.quickTime.slice(0,2);$('#taskMinute').value=b.dataset.quickTime.slice(3);sync()});sync()}
document.addEventListener('click',e=>{if(!e.target.closest('#deleteSchool'))return;let school=db.schools.find(s=>s.role===role&&s.name===schoolFilter);if(!school)return;let linked=db.students.some(s=>s.role===role&&s.school===school.name)||(role==='subject'&&db.assessments.some(a=>a.school===school.name))||(db.holidayEntries||[]).some(h=>h.schoolId===school.id);if(linked){alert('학생, 수행평가 또는 재량휴업일이 연결된 학교입니다. 학교 이름이 잘못되었다면 학교 이름 수정을 사용하세요. 삭제하려면 연결된 자료를 먼저 정리해 주세요.');return}if(!confirm(roleName()+'의 '+school.name+' 학교 등록을 삭제할까요? 다른 역할의 학교에는 영향을 주지 않습니다.'))return;let next={...db,schools:db.schools.filter(s=>s.id!==school.id)};try{if(storageError)throw Error(storageError);persistData(JSON.stringify(next));db=next;schoolFilter='';classFilter='';render();toast('학교 등록을 삭제했습니다.')}catch(err){toast('학교 삭제를 저장하지 못했습니다.')}});


function showSaveRecovery(){let el=document.getElementById('saveRecovery');if(!el){el=document.createElement('div');el.id='saveRecovery';el.setAttribute('role','alert');document.body.appendChild(el)}el.hidden=!writeConflict&&!unsavedChanges;el.innerHTML=(writeConflict?'다른 창에서 자료가 변경되어 저장을 중단했습니다. 이 창의 입력을 보관한 뒤 최신 자료를 불러오세요.':'아직 저장되지 않은 변경이 있습니다. 새로고침 전에 다시 저장하거나 백업하세요.')+' <button type="button" id="retryPendingSave" '+(writeConflict?'disabled':'')+'>다시 저장</button> <button type="button" id="recoveryBackup">이 창 JSON 백업</button> <button type="button" id="reloadLatestData">최신 자료 불러오기</button>'}
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){if(workspaceStorage.getItem(KEY)!==lastStored){writeConflict=true;showSaveRecovery()}}});
window.addEventListener('beforeunload',e=>{if(unsavedChanges){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',e=>{if(e.target.id==='retryPendingSave'){if(save())toast('변경을 반영했습니다. 상단 서버 저장 상태를 확인하세요.')}if(e.target.id==='recoveryBackup')exportFullBackup();if(e.target.id==='reloadLatestData'){if(confirm('이 창의 저장되지 않은 변경과 작성 중인 입력을 버리고 최신 저장 자료를 불러올까요?')){unsavedChanges=false;formBaseline=formSnapshot();rubricDirty=false;location.reload()}}});
const backupSettings=['_font','_focus','_holidayOverrides','_trash','_backupAt'];
async function exportFullBackup(){try{let settings={};for(let k of backupSettings){let v=workspaceStorage.getItem(KEY+k);if(v!==null)settings[k]=k==='_backupAt'?v:JSON.parse(v)}let font=null,prefs=settings._font;if(prefs?.fontId){let bytes=await fontStore('get',prefs.fontId);if(!bytes)throw Error('저장된 글꼴을 읽지 못했습니다. 글꼴을 다시 선택한 뒤 백업하세요.');font=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(new Blob([bytes]))})}let tabFonts={};for(let pref of Object.values(prefs?.tabs||{})){if(pref.fontId&&!tabFonts[pref.fontId]){let bytes=await fontStore('get',pref.fontId);if(!bytes)throw Error('탭 글꼴 파일을 찾지 못했습니다.');tabFonts[pref.fontId]=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(new Blob([bytes]))})}}let payload={backupFormat:2,createdAt:new Date().toISOString(),data:db,settings,font,tabFonts};let url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='교무수첩_전체백업_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);workspaceStorage.setItem(KEY+'_backupAt',new Date().toISOString());toast('데이터와 설정 백업 다운로드를 요청했습니다.')}catch(e){alert('백업 실패: '+e.message)}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="export"]')){e.preventDefault();e.stopImmediatePropagation();exportFullBackup()}},true);
$('#importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;let stagedFont=null,stagedTabFonts=[];try{if(file.size>500*1024*1024)throw Error('500MB 이하 JSON 파일을 선택하세요.');let payload=JSON.parse(await file.text()),full=payload.backupFormat===2,data=validate(full?payload.data:payload);migrateRosters(data);let settings=full?payload.settings:null;if(full){if(!settings||typeof settings!=='object'||Array.isArray(settings))throw Error('설정 형식이 올바르지 않습니다.');for(let key of Object.keys(settings))if(!backupSettings.includes(key))throw Error('지원하지 않는 설정입니다.');if(settings._trash&&!Array.isArray(settings._trash))throw Error('삭제 복구함 형식이 올바르지 않습니다.');if(settings._font&&(typeof settings._font!=='object'||Array.isArray(settings._font)))throw Error('글꼴 설정 형식이 올바르지 않습니다.');if(payload.font&&(typeof payload.font!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/=]+$/.test(payload.font)))throw Error('글꼴 자료 형식이 올바르지 않습니다.');}if(writeConflict||workspaceStorage.getItem(KEY)!==lastStored)throw Error('다른 창에서 변경되었습니다. 최신 자료를 불러온 뒤 복원하세요.');if(!confirm('백업의 학생 '+data.students.length+'명과 전체 기록'+(full?' 및 설정':'')+'으로 현재 자료를 교체할까요?'))return;if(full&&payload.font){let raw=atob(payload.font.split(',')[1]);if(raw.length>50*1024*1024)throw Error('글꼴 파일이 너무 큽니다.');let bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));await new FontFace('BackupFontCheck',bytes.buffer).load();stagedFont=uid();await fontStore('put',stagedFont,bytes.buffer);settings._font={...settings._font,fontId:stagedFont};delete settings._font.data;}else if(full&&settings._font?.fontId)throw Error('백업에 글꼴 파일이 없습니다.');if(full&&settings._font?.tabs){for(let pref of Object.values(settings._font.tabs)){if(!pref||typeof pref!=='object')throw Error('탭 글꼴 설정이 올바르지 않습니다.');if(pref.fontId){let encoded=payload.tabFonts?.[pref.fontId];if(typeof encoded!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/=]+$/.test(encoded))throw Error('탭 글꼴 파일이 없습니다.');let raw=atob(encoded.split(',')[1]);if(raw.length>50*1024*1024)throw Error('글꼴 파일이 너무 큽니다.');let bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));await new FontFace('TabBackupCheck',bytes.buffer).load();let id=uid();await fontStore('put',id,bytes.buffer);stagedTabFonts.push(id);pref.fontId=id;}}}let oldSettings=Object.fromEntries(backupSettings.map(k=>[k,workspaceStorage.getItem(KEY+k)]));try{if(full)for(let k of backupSettings){if(settings[k]===undefined)workspaceStorage.removeItem(KEY+k);else workspaceStorage.setItem(KEY+k,k==='_backupAt'?String(settings[k]):JSON.stringify(settings[k]))}persistData(JSON.stringify(data));}catch(err){for(let k of backupSettings){try{if(oldSettings[k]===null)workspaceStorage.removeItem(KEY+k);else workspaceStorage.setItem(KEY+k,oldSettings[k])}catch(ignored){}}throw err}db=data;storageError='';unsavedChanges=false;year=db.years[0];selected='';schoolFilter='';classFilter='';page='dashboard';assessmentId='';holidayMemory={};if(full){let focus=workspaceStorage.getItem(KEY+'_focus')==='true';document.body.classList.toggle('focus-mode',focus);$('#focusToggle').textContent=focus?'설정 펼치기 ↓':'설정 접기 ↑';$('#focusToggle').setAttribute('aria-expanded',String(!focus))}await applyFontPrefs(getFontPrefs()).catch(()=>{});render();toast('데이터'+(full?'와 설정':'')+'를 복원했습니다.');stagedFont=null;stagedTabFonts=[];}catch(err){for(let id of stagedTabFonts)await fontStore('delete',id).catch(()=>{});if(stagedFont)await fontStore('delete',stagedFont).catch(()=>{});alert('복원 실패: '+err.message)}finally{e.target.value=''}};



function taskRepeatDates(start,mode,end){if(mode==='none')return [start];if(!['daily','weekly','monthly'].includes(mode))throw Error('반복 종류를 확인하세요.');if(!start||!end||end<start)throw Error('반복 종료일은 시작일 이후로 선택하세요.');let base=new Date(start+'T12:00:00');if(!Number.isFinite(base.getTime()))throw Error('시작 날짜를 확인하세요.');let dates=[];for(let i=0;i<=366;i++){let d;if(mode==='monthly'){let first=new Date(base.getFullYear(),base.getMonth()+i,1,12);let last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();d=new Date(first.getFullYear(),first.getMonth(),Math.min(base.getDate(),last),12)}else{d=new Date(base);d.setDate(base.getDate()+i*(mode==='weekly'?7:1))}let key=calDate(d);if(key>end)return dates;dates.push(key);if(dates.length>366)throw Error('한 번에 최대 366개까지 등록할 수 있습니다. 종료일을 줄여 주세요.')}return dates}
function setupTaskRepeat(id){let box=document.createElement('div');box.className='field wide';if(id){box.innerHTML='<p class="muted">수정과 삭제는 선택한 날짜의 업무 한 건에만 적용됩니다.</p>';$('#fields').append(box);return}box.innerHTML='<div class="font-options">'+field('repeatMode','반복','select','none',{options:[['none','반복 안 함'],['daily','매일'],['weekly','매주 (시작일 요일)'],['monthly','매월 (시작일 날짜)']]})+field('repeatEnd','반복 종료일','date',$('#f-due').value,{required:false})+'</div><p class="muted" id="repeatPreview"></p>';$('#fields').append(box);let preview=()=>{let on=$('#f-repeatMode').value!=='none';$('#f-repeatEnd').disabled=!on;$('#f-repeatEnd').required=on;$('#f-repeatEnd').min=$('#f-due').value;try{let dates=taskRepeatDates($('#f-due').value,$('#f-repeatMode').value,$('#f-repeatEnd').value);$('#repeatPreview').textContent=on?dates.length+'개 일정을 등록합니다. 매월 해당 날짜가 없으면 말일에 등록합니다. 완료·수정·삭제는 각 일정에 따로 적용됩니다. 모든 회차는 현재 학년도에 보관됩니다.':''}catch(e){$('#repeatPreview').textContent=e.message}};$('#f-repeatMode').onchange=preview;$('#f-repeatEnd').onchange=preview;$('#f-due').addEventListener('change',preview);preview()}
function taskListHTML(){let text=taskSearchText.trim().toLocaleLowerCase(),items=taskScope().filter(t=>(taskListStatus==='all'||(taskListStatus==='done'?t.done:!t.done))&&(!text||(t.title+' '+t.category+' '+t.due).toLocaleLowerCase().includes(text))).sort((a,b)=>taskListStatus==='done'?b.due.localeCompare(a.due):a.due.localeCompare(b.due)||(a.time||'').localeCompare(b.time||''));return '<p class="muted">'+items.length+'건 / 현재 학년도와 교사 역할 기준, 학교와 표시 중인 달에 관계없이 검색합니다.</p>'+items.slice(0,taskListLimit).map(t=>'<div class="task-search-result">'+taskRow(t)+'<div class="actions"><button type="button" data-task-date="'+esc(t.due)+'">달력에서 보기</button>'+editButtons('tasks',t.id)+'</div></div>').join('')+(items.length===0?blank('조건에 맞는 업무가 없습니다.'):'')+(items.length>taskListLimit?'<button id="taskListMore">50건 더 보기</button>':'')}
function taskSearchPanelHTML(){return '<section class="card task-search-panel"><div class="card-head"><h2>일정 검색 / 완료 업무</h2><button class="primary" data-action="add" data-kind="tasks">＋ 업무 등록</button></div><div class="toolbar"><label class="task-search-label">제목 / 분류 / 날짜<input id="taskSearchInput" type="search" placeholder="예: 회의, 학생 상담, 2026-10" value="'+esc(taskSearchText)+'"></label><label>처리 상태<select id="taskListStatus"><option value="all" '+(taskListStatus==='all'?'selected':'')+'>전체 업무</option><option value="pending" '+(taskListStatus==='pending'?'selected':'')+'>미완료 업무</option><option value="done" '+(taskListStatus==='done'?'selected':'')+'>완료 업무 모아보기</option></select></label></div><div id="taskSearchResults">'+taskListHTML()+'</div></section>'}
