document.addEventListener('change',e=>{if(e.target.id==='taskListStatus'){taskListStatus=e.target.value;taskListLimit=50;$('#taskSearchResults').innerHTML=taskListHTML()}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='taskListMore'){taskListLimit+=50;$('#taskSearchResults').innerHTML=taskListHTML()}if(b.dataset.taskDate){calendarDate=b.dataset.taskDate;calendarMonth=calendarDate.slice(0,7);render();$('.calendar-panel').scrollIntoView({behavior:'smooth',block:'start'})}});

function taskPage(){let template=document.createElement('template');template.innerHTML=calendarTaskPage();let holiday=template.content.querySelector('.cal-sync'),bottom=document.createElement('div');bottom.className='calendar-bottom';holiday.before(bottom);bottom.append(holiday);bottom.insertAdjacentHTML('beforeend',taskSearchPanelHTML());return template.innerHTML}

